from django.db import migrations, models

# Legacy provider → dzship courier key, and only the credential values we are sure of.
# Missing credentials show as "incomplete" in settings for the owner to re-enter;
# nothing is guessed.
LEGACY_COURIER = {
    "maystro": "maystro",
    "yalidine": "yalidine",
    "noest": "noest",
    "zr_express": "zrexpress",
}

SECRET_PAYLOAD_KEYS = ("api_id", "api_secret", "credentials", "access_token")
SCRUBBED_MODELS = ("ProviderConfig", "SocialIntegration")


def _legacy_credentials(provider, api_id, api_secret):
    api_id = (api_id or "").strip()
    api_secret = (api_secret or "").strip()
    if provider == "maystro":
        # dispatch sent api_secret; the old form only required the first field (api_id).
        value = api_secret or api_id
        return {"apiKey": value} if value else {}
    if provider == "yalidine":
        creds = {}
        if api_id:
            creds["apiId"] = api_id
        if api_secret:
            creds["apiToken"] = api_secret
        return creds
    if provider == "noest":
        # The old form had no GUID field; only the token is certain.
        return {"apiToken": api_secret} if api_secret else {}
    # zr_express: the old mapping did not match ZR's credential names; re-enter.
    return {}


def fill_courier_and_credentials(apps, schema_editor):
    ProviderConfig = apps.get_model("delivery_integrations", "ProviderConfig")
    rows = (
        ProviderConfig.objects.filter(courier="")
        .exclude(provider="")
        .only("id", "provider", "api_id", "api_secret")
    )
    for row in rows.iterator(chunk_size=200):
        courier = LEGACY_COURIER.get(row.provider)
        if not courier:
            continue
        ProviderConfig.objects.filter(pk=row.pk, courier="").update(
            courier=courier,
            credentials=_legacy_credentials(row.provider, row.api_id, row.api_secret),
        )


def scrub_secrets_from_sync_outbox(apps, schema_editor):
    SyncOutbox = apps.get_model("core", "SyncOutbox")
    rows = SyncOutbox.objects.filter(model_name__in=SCRUBBED_MODELS).only("id", "payload")
    for row in rows.iterator(chunk_size=500):
        payload = row.payload if isinstance(row.payload, dict) else {}
        if any(key in payload for key in SECRET_PAYLOAD_KEYS):
            cleaned = {k: v for k, v in payload.items() if k not in SECRET_PAYLOAD_KEYS}
            SyncOutbox.objects.filter(pk=row.pk).update(payload=cleaned)


